package com.nvv.mediadata.data.module.utilsimport com.google.firebase.auth.FirebaseAuthimport com.google.firebase.firestore.FirebaseFirestoreimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport javax.inject.Namedimport javax.inject.Singleton@Module@InstallIn(SingletonComponent::class)object FirebaseModule {	@Provides	@Singleton	@Named("Firebase-Auth")	fun firebaseAuth() : FirebaseAuth {		return FirebaseAuth.getInstance()	}	@Provides	@Singleton	@Named("Firestore")	fun firestore() : FirebaseFirestore {		return FirebaseFirestore.getInstance()	}}